import android.Manifest;import android.app.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.media.MediaPlayer;import android.os.*;import android.provider.Settings;import android.text.InputType;import android.view.*;import android.widget.*;import java.io.*;import java.net.*;import java.util.*;import org.json.*;

public class MainActivity extends Activity{
 android.content.SharedPreferences prefs;LinearLayout root,content,operatorPanel,notificationPanel,accountPanel;EditText server,user,password;TextView loginStatus,currentNumber,waitingText,customAudioStatus;Spinner serviceSpinner,counterSpinner,soundSpinner,modeSpinner;SeekBar volumeBar;CheckBox notificationEnabled;JSONArray serviceData=new JSONArray(),counterData=new JSONArray();ArrayList<Button> tabButtons=new ArrayList<Button>();int currentTicketId=0;android.net.Uri selectedAudioUri;
 int dp(int v){return(int)(v*getResources().getDisplayMetrics().density+.5f);}TextView text(String s,int size,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(Color.rgb(10,39,75));if(bold)v.setTypeface(null,1);v.setPadding(0,dp(5),0,dp(5));return v;}LinearLayout.LayoutParams margins(int top,int bottom){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(top),0,dp(bottom));return p;}
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("reka",MODE_PRIVATE);if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},7);if(prefs.contains("token")){QueueService.start(this);showMain();}else showLogin();}
 protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==41&&resultCode==RESULT_OK&&data!=null&&data.getData()!=null){selectedAudioUri=data.getData();try{getContentResolver().takePersistableUriPermission(selectedAudioUri,data.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}customAudioStatus.setText("Mengunggah audio…");uploadCustomAudio(selectedAudioUri);}}
 public boolean onKeyDown(int keyCode,android.view.KeyEvent event){if(keyCode==android.view.KeyEvent.KEYCODE_VOLUME_DOWN){QueueService.stopSound(this);Toast.makeText(this,"Suara notifikasi dihentikan.",Toast.LENGTH_SHORT).show();return true;}return super.onKeyDown(keyCode,event);}
 void baseScreen(){ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(Color.rgb(239,245,251));root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(22),dp(28),dp(22),dp(28));scroll.addView(root);LinearLayout brand=new LinearLayout(this);brand.setGravity(Gravity.CENTER_VERTICAL);TextView mark=text("RQ",20,true);mark.setTextColor(Color.rgb(7,59,92));mark.setGravity(17);mark.setBackgroundColor(Color.rgb(255,210,63));brand.addView(mark,new LinearLayout.LayoutParams(dp(52),dp(52)));TextView title=text("  Reka Queue Operator",23,true);brand.addView(title);root.addView(brand);setContentView(scroll);}
 void showLogin(){baseScreen();root.addView(text("Masuk ke perangkat",30,true),margins(30,2));TextView lead=text("Hubungkan satu kali menggunakan akun operator Anda.",16,false);lead.setTextColor(Color.rgb(91,111,134));root.addView(lead);LinearLayout card=panel();root.addView(card,margins(24,0));server=field(card,"Alamat server",prefs.getString("server",""),InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);server.setHint("http://alamat-server:8090");user=field(card,"Username operator",prefs.getString("username",""),InputType.TYPE_CLASS_TEXT);password=field(card,"Password", "",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);Button login=primary("MASUK & HUBUNGKAN");card.addView(login,new LinearLayout.LayoutParams(-1,dp(56)));loginStatus=text("Password hanya digunakan saat pendaftaran perangkat.",14,false);card.addView(loginStatus);login.setOnClickListener(new View.OnClickListener(){public void onClick(View v){register();}});}
 void showMain(){baseScreen();LinearLayout top=new LinearLayout(this);top.setOrientation(LinearLayout.HORIZONTAL);top.setGravity(Gravity.CENTER_VERTICAL);TextView welcome=text("Operator · "+prefs.getString("username",""),14,true);top.addView(welcome,new LinearLayout.LayoutParams(0,-2,1));Button exit=new Button(this);exit.setText("KELUAR");flat(exit,Color.rgb(180,35,24));top.addView(exit,new LinearLayout.LayoutParams(dp(100),dp(44)));root.addView(top,margins(14,8));exit.setOnClickListener(new View.OnClickListener(){public void onClick(View v){signOut();}});
  LinearLayout tabs=new LinearLayout(this);tabs.setOrientation(LinearLayout.HORIZONTAL);root.addView(tabs,margins(4,12));tab(tabs,"OPERATOR",0);tab(tabs,"NOTIFIKASI",1);tab(tabs,"AKUN",2);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);root.addView(content);buildOperator();buildNotifications();buildAccount();showTab(0);}
 LinearLayout panel(){LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(20),dp(18),dp(20),dp(18));p.setBackgroundResource(R.drawable.panel);return p;}void flat(Button b,int color){GradientDrawable bg=new GradientDrawable();bg.setColor(color);bg.setCornerRadius(dp(9));b.setBackground(bg);b.setTextColor(Color.WHITE);b.setTypeface(null,1);b.setStateListAnimator(null);}EditText field(LinearLayout p,String label,String value,int type){p.addView(text(label,14,true));EditText e=new EditText(this);e.setText(value);e.setTextSize(16);e.setSingleLine(true);e.setInputType(type);e.setTextColor(Color.rgb(10,39,75));e.setPadding(dp(14),0,dp(14),0);GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(dp(9));bg.setStroke(dp(1),Color.rgb(190,207,225));e.setBackground(bg);LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-1,dp(54));ep.setMargins(0,dp(5),0,dp(12));p.addView(e,ep);return e;}Button primary(String label){Button b=new Button(this);b.setText(label);b.setTextSize(14);flat(b,Color.rgb(20,120,200));return b;}
 void tab(LinearLayout row,String label,final int index){Button b=new Button(this);b.setText(label);b.setTextSize(11);flat(b,Color.rgb(208,222,238));b.setTextColor(Color.rgb(18,60,96));tabButtons.add(b);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(50),1);p.setMargins(dp(2),0,dp(2),0);row.addView(b,p);b.setOnClickListener(new View.OnClickListener(){public void onClick(View v){showTab(index);}});}void showTab(int n){operatorPanel.setVisibility(n==0?View.VISIBLE:View.GONE);notificationPanel.setVisibility(n==1?View.VISIBLE:View.GONE);accountPanel.setVisibility(n==2?View.VISIBLE:View.GONE);for(int i=0;i<tabButtons.size();i++){flat(tabButtons.get(i),i==n?Color.rgb(7,95,145):Color.rgb(208,222,238));tabButtons.get(i).setTextColor(i==n?Color.WHITE:Color.rgb(18,60,96));}if(n==1)loadNotificationSettings();}
 void buildOperator(){operatorPanel=panel();content.addView(operatorPanel);operatorPanel.addView(text("Konsol operator",25,true));operatorPanel.addView(text("Layanan",13,true));serviceSpinner=new Spinner(this);operatorPanel.addView(serviceSpinner,new LinearLayout.LayoutParams(-1,dp(52)));operatorPanel.addView(text("Loket",13,true));counterSpinner=new Spinner(this);operatorPanel.addView(counterSpinner,new LinearLayout.LayoutParams(-1,dp(52)));waitingText=text("Menunggu: —",17,true);operatorPanel.addView(waitingText);currentNumber=text("— — —",44,true);currentNumber.setGravity(17);currentNumber.setTextColor(Color.rgb(20,120,200));operatorPanel.addView(currentNumber,new LinearLayout.LayoutParams(-1,dp(100)));LinearLayout row=new LinearLayout(this);operatorPanel.addView(row);actionButton(row,"PANGGIL ULANG","recall",Color.rgb(7,139,70));actionButton(row,"BERIKUTNYA","next",Color.rgb(20,120,200));LinearLayout states=new LinearLayout(this);operatorPanel.addView(states);actionButton(states,"LAYANI","serve",Color.rgb(37,99,235));actionButton(states,"SELESAI","complete",Color.rgb(15,159,130));actionButton(states,"LEWATI","skip",Color.rgb(217,119,6));android.widget.AdapterView.OnItemSelectedListener listener=new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int x,long id){refreshState();}};serviceSpinner.setOnItemSelectedListener(listener);counterSpinner.setOnItemSelectedListener(listener);loadOperator();}
 void buildNotifications(){notificationPanel=panel();content.addView(notificationPanel);notificationPanel.addView(text("Notifikasi lintas perangkat",25,true));TextView info=text("Pengaturan tersimpan di server untuk akun operator ini.",14,false);info.setTextColor(Color.rgb(91,111,134));notificationPanel.addView(info);notificationEnabled=new CheckBox(this);notificationEnabled.setText("Aktifkan notifikasi antrean baru");notificationEnabled.setTextSize(16);notificationPanel.addView(notificationEnabled,margins(14,8));notificationPanel.addView(text("Suara",13,true));soundSpinner=new Spinner(this);soundSpinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Chime","Bell","Beep","Custom audio"}));notificationPanel.addView(soundSpinner,new LinearLayout.LayoutParams(-1,dp(52)));Button choose=primary("PILIH & UPLOAD AUDIO CUSTOM");flat(choose,Color.rgb(91,73,190));notificationPanel.addView(choose,new LinearLayout.LayoutParams(-1,dp(54)));choose.setOnClickListener(new View.OnClickListener(){public void onClick(View v){Intent pick=new Intent(Intent.ACTION_OPEN_DOCUMENT);pick.addCategory(Intent.CATEGORY_OPENABLE);pick.setType("audio/*");startActivityForResult(pick,41);}});customAudioStatus=text("MP3, WAV, atau OGG · maksimal 10 MB",13,false);customAudioStatus.setTextColor(Color.rgb(91,111,134));notificationPanel.addView(customAudioStatus);notificationPanel.addView(text("Volume",13,true));volumeBar=new SeekBar(this);volumeBar.setMax(100);notificationPanel.addView(volumeBar);notificationPanel.addView(text("Setelah antrean dipanggil",13,true));modeSpinner=new Spinner(this);modeSpinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Hilang dan berhenti","Tetap tampil dan putar"}));notificationPanel.addView(modeSpinner,new LinearLayout.LayoutParams(-1,dp(52)));Button test=primary("SINKRONKAN & TES SUARA");flat(test,Color.rgb(7,139,70));LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(-1,dp(54));tp.setMargins(0,dp(10),0,dp(8));notificationPanel.addView(test,tp);test.setOnClickListener(new View.OnClickListener(){public void onClick(View v){syncAndTestSound();}});Button save=primary("SIMPAN PENGATURAN");notificationPanel.addView(save,new LinearLayout.LayoutParams(-1,dp(56)));save.setOnClickListener(new View.OnClickListener(){public void onClick(View v){saveNotificationSettings();}});}
 void buildAccount(){accountPanel=panel();content.addView(accountPanel);accountPanel.addView(text("Akun & server",25,true));accountPanel.addView(text("Username",13,true));accountPanel.addView(text(prefs.getString("username","-"),18,true));accountPanel.addView(text("Alamat server",13,true));accountPanel.addView(text(prefs.getString("server","-"),16,false));TextView note=text("Untuk pindah server atau akun, keluar lalu hubungkan perangkat kembali.",14,false);note.setTextColor(Color.rgb(91,111,134));accountPanel.addView(note,margins(16,8));Button web=new Button(this);web.setText("BUKA KONSOL WEB");accountPanel.addView(web,new LinearLayout.LayoutParams(-1,dp(54)));web.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(base()+"/operator")));}});}
 void actionButton(LinearLayout row,String label,final String action,int color){Button b=new Button(this);b.setText(label);b.setTextSize(11);flat(b,color);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(54),1);p.setMargins(dp(3),dp(5),dp(3),dp(5));row.addView(b,p);b.setOnClickListener(new View.OnClickListener(){public void onClick(View v){operatorAction(action);}});}
 void register(){final String s=server.getText().toString().trim().replaceAll("/+$","");final String u=user.getText().toString().trim(),pw=password.getText().toString();if(s.isEmpty()||u.isEmpty()||pw.isEmpty()){loginStatus.setText("Semua kolom wajib diisi.");return;}loginStatus.setText("Menghubungkan…");new Thread(new Runnable(){public void run(){try{String device=Settings.Secure.getString(getContentResolver(),Settings.Secure.ANDROID_ID);String body="username="+URLEncoder.encode(u,"UTF-8")+"&password="+URLEncoder.encode(pw,"UTF-8")+"&device_id="+URLEncoder.encode(device,"UTF-8")+"&device_name="+URLEncoder.encode(Build.MANUFACTURER+" "+Build.MODEL+" (Android)","UTF-8");JSONObject d=api(s+"/api/client/notifications/register",body,null).getJSONObject("data");prefs.edit().putString("server",s).putString("username",u).putString("token",d.getString("token")).putLong("cursor",d.optLong("cursor",0)).apply();runOnUiThread(new Runnable(){public void run(){recreate();}});}catch(final Exception e){runOnUiThread(new Runnable(){public void run(){loginStatus.setText("Gagal: "+e.getMessage());}});}}}).start();}
 void signOut(){stopService(new Intent(this,QueueService.class));prefs.edit().remove("token").remove("cursor").apply();recreate();}
 int selectedId(JSONArray a,Spinner s){if(s==null||a.length()==0)return 0;JSONObject o=a.optJSONObject(s.getSelectedItemPosition());return o==null?0:o.optInt("id");}
 void loadOperator(){new Thread(new Runnable(){public void run(){try{JSONObject d=api(base()+"/api/client/operator-state",null,token()).getJSONObject("data");serviceData=d.getJSONArray("services");counterData=d.getJSONArray("counters");final ArrayList<String> ss=new ArrayList<String>(),cc=new ArrayList<String>();for(int i=0;i<serviceData.length();i++)ss.add(serviceData.getJSONObject(i).getString("name"));for(int i=0;i<counterData.length();i++)cc.add(counterData.getJSONObject(i).getString("name"));runOnUiThread(new Runnable(){public void run(){serviceSpinner.setAdapter(new ArrayAdapter<String>(MainActivity.this,android.R.layout.simple_spinner_dropdown_item,ss));counterSpinner.setAdapter(new ArrayAdapter<String>(MainActivity.this,android.R.layout.simple_spinner_dropdown_item,cc));refreshState();}});}catch(Exception e){showError(e);}}}).start();}
 void refreshState(){if(serviceData.length()==0||counterData.length()==0)return;final int sid=selectedId(serviceData,serviceSpinner),cid=selectedId(counterData,counterSpinner);new Thread(new Runnable(){public void run(){try{final JSONObject d=api(base()+"/api/client/operator-state?service_id="+sid+"&counter_id="+cid,null,token()).getJSONObject("data");runOnUiThread(new Runnable(){public void run(){waitingText.setText("Menunggu: "+d.optInt("waiting"));JSONObject c=d.optJSONObject("current");currentTicketId=c==null?0:c.optInt("id");currentNumber.setText(c==null?"— — —":c.optString("ticket_number"));}});}catch(Exception e){showError(e);}}}).start();}
 void operatorAction(final String action){final int sid=selectedId(serviceData,serviceSpinner),cid=selectedId(counterData,counterSpinner);if(!action.equals("next")&&currentTicketId==0){Toast.makeText(this,"Belum ada antrean aktif.",Toast.LENGTH_SHORT).show();return;}new Thread(new Runnable(){public void run(){try{String body="action="+action+"&service_id="+sid+"&counter_id="+cid+"&ticket_id="+currentTicketId;api(base()+"/api/client/operator-action",body,token());runOnUiThread(new Runnable(){public void run(){refreshState();}});}catch(Exception e){showError(e);}}}).start();}
 void loadNotificationSettings(){new Thread(new Runnable(){public void run(){try{final JSONObject d=api(base()+"/api/client/notification-settings",null,token()).getJSONObject("data");runOnUiThread(new Runnable(){public void run(){notificationEnabled.setChecked(d.optBoolean("enabled",true));String[] values={"chime","bell","beep","custom"};String type=d.optString("sound_type","chime");for(int i=0;i<values.length;i++)if(values[i].equals(type))soundSpinner.setSelection(i);volumeBar.setProgress((int)(d.optDouble("volume",.8)*100));modeSpinner.setSelection("persistent".equals(d.optString("play_mode"))?1:0);}});}catch(Exception e){showError(e);}}}).start();}
 void syncAndTestSound(){new Thread(new Runnable(){public void run(){try{final JSONObject d=api(base()+"/api/client/notification-settings",null,token()).getJSONObject("data");String type=d.optString("sound_type","chime"),sound=d.optString("sound_url","");if(!type.equals("custom")||sound.isEmpty()){if(!type.equals("bell")&&!type.equals("beep"))type="chime";sound="/assets/sounds/"+type+".wav";}if(sound.startsWith("/"))sound=base()+sound;sound+=(sound.contains("?")?"&":"?")+"manual_sync="+System.currentTimeMillis();final float volume=(float)d.optDouble("volume",.8);final MediaPlayer player=new MediaPlayer();player.setDataSource(sound);player.setVolume(volume,volume);player.setOnPreparedListener(new MediaPlayer.OnPreparedListener(){public void onPrepared(MediaPlayer m){m.start();runOnUiThread(new Runnable(){public void run(){Toast.makeText(MainActivity.this,"Audio terbaru berhasil dimuat.",Toast.LENGTH_SHORT).show();}});}});player.setOnCompletionListener(new MediaPlayer.OnCompletionListener(){public void onCompletion(MediaPlayer m){m.release();}});player.prepareAsync();stopService(new Intent(MainActivity.this,QueueService.class));QueueService.start(MainActivity.this);runOnUiThread(new Runnable(){public void run(){loadNotificationSettings();}});}catch(Exception e){showError(e);}}}).start();}
 void saveNotificationSettings(){String[] sounds={"chime","bell","beep","custom"};final String body="enabled="+(notificationEnabled.isChecked()?"1":"0")+"&sound_type="+sounds[soundSpinner.getSelectedItemPosition()]+"&volume="+(volumeBar.getProgress()/100.0)+"&play_mode="+(modeSpinner.getSelectedItemPosition()==1?"persistent":"auto");new Thread(new Runnable(){public void run(){try{api(base()+"/api/client/notification-settings",body,token());runOnUiThread(new Runnable(){public void run(){Toast.makeText(MainActivity.this,"Pengaturan tersimpan untuk semua perangkat.",Toast.LENGTH_LONG).show();}});}catch(Exception e){showError(e);}}}).start();}
 void uploadCustomAudio(final android.net.Uri uri){new Thread(new Runnable(){public void run(){try{String mime=getContentResolver().getType(uri);if(mime==null)mime="audio/mpeg";InputStream input=getContentResolver().openInputStream(uri);if(input==null)throw new Exception("File audio tidak dapat dibaca.");final JSONObject result=upload(base()+"/api/client/notification-audio",input,mime,token()).getJSONObject("data");runOnUiThread(new Runnable(){public void run(){soundSpinner.setSelection(3);customAudioStatus.setText("Audio custom terbaru tersimpan.");Toast.makeText(MainActivity.this,"Upload berhasil. Audio custom sudah aktif.",Toast.LENGTH_LONG).show();syncAndTestSound();}});}catch(final Exception e){runOnUiThread(new Runnable(){public void run(){customAudioStatus.setText("Upload gagal: "+e.getMessage());}});}}}).start();}
 String base(){return prefs.getString("server","");}String token(){return prefs.getString("token","");}void showError(final Exception e){runOnUiThread(new Runnable(){public void run(){Toast.makeText(MainActivity.this,e.getMessage(),Toast.LENGTH_LONG).show();}});}
 static JSONObject upload(String url,InputStream input,String mime,String token)throws Exception{String boundary="----RekaQueue"+System.currentTimeMillis();HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(30000);c.setReadTimeout(30000);c.setRequestMethod("POST");c.setDoOutput(true);c.setChunkedStreamingMode(8192);c.setRequestProperty("Accept","application/json");c.setRequestProperty("X-Device-Token",token);c.setRequestProperty("Content-Type","multipart/form-data; boundary="+boundary);DataOutputStream out=new DataOutputStream(c.getOutputStream());out.writeBytes("--"+boundary+"\r\n");out.writeBytes("Content-Disposition: form-data; name=\"sound_file\"; filename=\"android-audio\"\r\n");out.writeBytes("Content-Type: "+mime+"\r\n\r\n");byte[] buffer=new byte[8192];int n,total=0;while((n=input.read(buffer))!=-1){total+=n;if(total>10*1024*1024){input.close();out.close();throw new Exception("Ukuran audio maksimal 10 MB.");}out.write(buffer,0,n);}input.close();out.writeBytes("\r\n--"+boundary+"--\r\n");out.close();InputStream response=c.getResponseCode()<400?c.getInputStream():c.getErrorStream();JSONObject json=new JSONObject(read(response));if(c.getResponseCode()>=400)throw new Exception(json.optString("error","Upload gagal"));return json;}
 static JSONObject api(String url,String body,String token)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestProperty("Accept","application/json");if(token!=null)c.setRequestProperty("X-Device-Token",token);if(body!=null){c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/x-www-form-urlencoded");try(OutputStream o=c.getOutputStream()){o.write(body.getBytes("UTF-8"));}}InputStream in=c.getResponseCode()<400?c.getInputStream():c.getErrorStream();JSONObject r=new JSONObject(read(in));if(c.getResponseCode()>=400)throw new Exception(r.optString("error","Server error"));return r;}static String read(InputStream in)throws IOException{BufferedReader b=new BufferedReader(new InputStreamReader(in));StringBuilder s=new StringBuilder();String l;while((l=b.readLine())!=null)s.append(l);return s.toString();}
}
